L000043	\title{Parity-Doublet Coherence Times in Optically Trapped Polyatomic Molecules}
L000044	
L000045	\author{Paige Robichaud}
L000046	\email{paigerobichaud@g.harvard.edu}
L000047	\author{Christian Hallas}
L000048	\author{Junheng Tao}
